import { BooleanColumn, Table, StringColumn } from '../../db'
import { PropertyTypeChoices } from './sys_properties.now'

export const sys_user_preference = Table({
    name: 'sys_user_preference',
    schema: {
        name: StringColumn({ mandatory: true }),
        type: StringColumn({
            mandatory: true,
            choices: PropertyTypeChoices,
        }),
        value: StringColumn({}),
        description: StringColumn({}),
        system: BooleanColumn({}),
    },
})
